// Simple hash set for strings (could use trie for speed, but this works for constraints)
bool match_at(int pos, int idx) {
    int len = str_len[idx];
    if (pos + len > t_len) return false;
    for (int j = 0; j < len; j++) {
        if (t[pos + j] != strings[idx][j]) return false;
