#define MOD 1000000007
#define MAXN 100005
#define ALPHA 26

typedef struct {
    int children[ALPHA];
    int fail;
    int output; // length of matched pattern, -1 if none (store list via linked output links)
    int dict_suffix; // link to next node with output via suffix links
} AhoNode;

AhoNode aho[MAXN * 10];
int aho_size;

// We'll store output lengths in a list per node
// Actually, let's store sum of dp contributions differently
// For each node, store all pattern lengths that end here
// Use output link chain

int pat_len[MAXN]; // lengths of patterns ending at each aho node (0 if none)
// Actually nodes can have multiple patterns - but problem says N different strings
// Multiple patterns can end at same node only if one is suffix of another
// We need to handle all of them

// Let's store: for each aho node, a linked list of pattern lengths
int node_len[MAXN * 10]; // if this node itself is end of pattern, its length
int node_dict[MAXN * 10]; // dict suffix link

void aho_init() {
    aho_size = 1;
    memset(aho[0].children, -1, sizeof(aho[0].children));
    aho[0].fail = 0;
    aho[0].output = -1;
    node_len[0] = 0;
    node_dict[0] = 0;
}

int aho_add(const char *s, int len) {
    int cur = 0;
    for (int i = 0; i < len; i++) {
        int c = s[i] - 'a';
        if (aho[cur].children[c] == -1) {
            memset(aho[aho_size].children, -1, sizeof(aho[aho_size].children));
            aho[aho_size].fail = 0;
            aho[aho_size].output = -1;
            node_len[aho_size] = 0;
            node_dict[aho_size] = 0;
            aho[cur].children[c] = aho_size++;
        }
        cur = aho[cur].children[c];
    }
    node_len[cur] = len;
    return cur;
}

int queue[MAXN * 10];

void aho_build() {
    int head = 0, tail = 0;
    for (int c = 0; c < ALPHA; c++) {
        if (aho[0].children[c] == -1) aho[0].children[c] = 0;
        else { aho[aho[0].children[c]].fail = 0; queue[tail++] = aho[0].children[c]; }
    }
    while (head < tail) {
        int u = queue[head++];
        int f = aho[u].fail;
        node_dict[u] = (node_len[f] > 0) ? f : node_dict[f];
        for (int c = 0; c < ALPHA; c++) {
            if (aho[u].children[c] == -1) aho[u].children[c] = aho[f].children[c];
            else { aho[aho[u].children[c]].fail = aho[f].children[c]; queue[tail++] = aho[u].children[c]; }
        }
    }
}

long long dp[MAXN];
char t[MAXN];
char buf[MAXN];

int main() {
    int n;
    scanf("%d", &n);
    scanf("%s", t);
    int tlen = strlen(t);

    aho_init();
    for (int i = 0; i < n; i++) {
        scanf("%s", buf);
        aho_add(buf, strlen(buf));
    }
    aho_build();

    dp[0] = 1;
    int cur = 0;
    for (int i = 0; i < tlen; i++) {
        dp[i+1] = 0;
        cur = aho[cur].children[t[i]-'a'];
        // collect all pattern lengths ending at position i
        int v = cur;
        if (node_len[v] > 0) {
            int start = i + 1 - node_len[v];
            if (start >= 0) dp[i+1] = (dp[i+1] + dp[start]) % MOD;
        }
        v = node_dict[cur];
        while (v > 0) {
            int start = i + 1 - node_len[v];
            if (start >= 0) dp[i+1] = (dp[i+1] + dp[start]) % MOD;
            v = node_dict[v];
        }
    }
    printf("%lld\n", dp[tlen]);
    return 0;
}

