#define MOD 1000000007LL

typedef struct TrieNode {
    int end;
    int next[26];
} TrieNode;

static TrieNode *trie = NULL;
static int trieSize = 0, trieCap = 0;

static void ensureTrieCap() {
    if (trieSize >= trieCap) {
        trieCap = (trieCap == 0 ? 1024 : trieCap * 2);
        trie = (TrieNode *)realloc(trie, trieCap * sizeof(TrieNode));
    }
}

static int newNode() {
    ensureTrieCap();
    int id = trieSize++;
    trie[id].end = 0;
    for (int i = 0; i < 26; i++) trie[id].next[i] = -1;
    return id;
}

static void insertWord(const char *s) {
    int cur = 0;
    for (int i = 0; s[i]; i++) {
        int c = s[i] - 'a';
        if (trie[cur].next[c] == -1) {
            trie[cur].next[c] = newNode();
        }
        cur = trie[cur].next[c];
    }
    trie[cur].end = 1;
}

int main() {
    char *t = (char *)malloc(1000005);
    if (scanf("%1000000s", t) != 1) return 0;

    int N;
    scanf("%d", &N);

    newNode(); // root

    char *w = (char *)malloc(1000005);
    for (int i = 0; i < N; i++) {
        scanf("%1000000s", w);
        insertWord(w);
    }

    int m = (int)strlen(t);
    long long *dp = (long long *)calloc(m + 1, sizeof(long long));
    dp[m] = 1;

    for (int i = m - 1; i >= 0; i--) {
        int cur = 0;
        long long ways = 0;
        for (int j = i; j < m; j++) {
            int c = t[j] - 'a';
            if (c < 0 || c >= 26 || trie[cur].next[c] == -1) break;
            cur = trie[cur].next[c];
            if (trie[cur].end) {
                ways += dp[j + 1];
                if (ways >= MOD) ways -= MOD;
            }
        }
        dp[i] = ways;
    }

    printf("%lld\n", dp[0] % MOD);

    free(t);
    free(w);
    free(dp);
    free(trie);
    return 0;
}

