const int MOD = 1e9 + 7;

struct AhoCorasick {
    vector<array<int,26>> go;
    vector<int> fail, out_len; // out_len stores length of pattern ending here via suffix links
    // We'll store list of pattern lengths at each node
    vector<vector<int>> patterns;

    AhoCorasick() {
        go.push_back({});
        fill(go[0].begin(), go[0].end(), -1);
        fail.push_back(0);
        patterns.push_back({});
    }

    void insert(const string& s) {
        int cur = 0;
        for (char c : s) {
            int ch = c - 'a';
            if (go[cur][ch] == -1) {
                go[cur][ch] = go.size();
                go.push_back({});
                fill(go.back().begin(), go.back().end(), -1);
                fail.push_back(0);
                patterns.push_back({});
            }
            cur = go[cur][ch];
        }
        patterns[cur].push_back(s.size());
    }

    void build() {
        queue<int> q;
        for (int c = 0; c < 26; c++) {
            if (go[0][c] == -1) go[0][c] = 0;
            else {
                fail[go[0][c]] = 0;
                q.push(go[0][c]);
            }
        }
        while (!q.empty()) {
            int u = q.front(); q.pop();
            // merge patterns from fail link
            for (int len : patterns[fail[u]])
                patterns[u].push_back(len);
            for (int c = 0; c < 26; c++) {
                if (go[u][c] == -1) {
                    go[u][c] = go[fail[u]][c];
                } else {
                    fail[go[u][c]] = go[fail[u]][c];
                    q.push(go[u][c]);
                }
            }
        }
    }
};

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string t;
    int n;
    cin >> t >> n;

    AhoCorasick ac;
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        ac.insert(s);
    }
    ac.build();

    int len = t.size();
    vector<long long> dp(len+1, 0);
    dp[0] = 1;

    int cur = 0;
    for (int i = 0; i < len; i++) {
        int ch = t[i] - 'a';
        cur = ac.go[cur][ch];
        // all patterns ending at position i (0-indexed), i.e., at position i+1 in dp
        for (int plen : ac.patterns[cur]) {
            dp[i+1] = (dp[i+1] + dp[i+1-plen]) % MOD;
        }
    }

    cout << dp[len] << endl;

    return 0;
}

