static const long long MOD = 1000000007LL;

struct Node {
    int next[26];
    bool terminal;
    Node() {
        memset(next, -1, sizeof(next));
        terminal = false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string t;
    int N;
    cin >> t >> N;

    vector<Node> trie(1);

    for (int i = 0; i < N; ++i) {
        string s;
        cin >> s;
        int cur = 0;
        for (char c : s) {
            int x = c - 'a';
            if (trie[cur].next[x] == -1) {
                trie[cur].next[x] = (int)trie.size();
                trie.emplace_back();
            }
            cur = trie[cur].next[x];
        }
        trie[cur].terminal = true;
    }

    int m = (int)t.size();
    vector<long long> dp(m + 1, 0);
    dp[m] = 1;

    for (int i = m - 1; i >= 0; --i) {
        int cur = 0;
        for (int j = i; j < m; ++j) {
            int x = t[j] - 'a';
            if (trie[cur].next[x] == -1) break;
            cur = trie[cur].next[x];
            if (trie[cur].terminal) {
                dp[i] += dp[j + 1];
                if (dp[i] >= MOD) dp[i] -= MOD;
            }
        }
    }

    cout << dp[0] % MOD << '\n';
    return 0;
}

