import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;
    static final long BASE = 911382323L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String t = fs.next();
        int n = fs.nextInt();

        int m = t.length();

        long[] pow = new long[m + 1];
        long[] pref = new long[m + 1];
        pow[0] = 1;
        for (int i = 0; i < m; i++) {
            pow[i + 1] = (pow[i] * BASE) % MOD;
            pref[i + 1] = (pref[i] * BASE + t.charAt(i)) % MOD;
        }

        HashMap<Integer, HashSet<Long>> byLen = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String s = fs.next();
            long h = 0;
            for (int j = 0; j < s.length(); j++) {
                h = (h * BASE + s.charAt(j)) % MOD;
            }
            byLen.computeIfAbsent(s.length(), k -> new HashSet<>()).add(h);
        }

        ArrayList<Integer> lengths = new ArrayList<>(byLen.keySet());
        Collections.sort(lengths);

        long[] dp = new long[m + 1];
        dp[0] = 1;

        for (int i = 0; i < m; i++) {
            if (dp[i] == 0) continue;
            for (int len : lengths) {
                int r = i + len;
                if (r > m) break;
                long subHash = getHash(pref, pow, i, r);
                HashSet<Long> set = byLen.get(len);
                if (set.contains(subHash)) {
                    dp[r] += dp[i];
                    if (dp[r] >= MOD) dp[r] -= MOD;
                }
            }
        }

        System.out.println(dp[m] % MOD);
    }

    static long getHash(long[] pref, long[] pow, int l, int r) {
        long val = pref[r] - (pref[l] * pow[r - l]) % MOD;
        if (val < 0) val += MOD;
        return val;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

