import sys

MOD = 1_000_000_007
BASE = 911382323
MASK = (1 << 64) - 1

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    t = data[0]
    n = int(data[1])
    words = data[2:2 + n]

    m = len(t)

    # Group dictionary words by length, storing 64-bit rolling hashes
    by_len = {}
    for w in words:
        h = 0
        for ch in w:
            h = ((h * BASE) + ord(ch)) & MASK
        L = len(w)
        if L not in by_len:
            by_len[L] = set()
        by_len[L].add(h)

    lengths = sorted(by_len.keys())

    # Prefix hashes for t
    pref = [0] * (m + 1)
    power = [1] * (m + 1)
    for i, ch in enumerate(t):
        pref[i + 1] = ((pref[i] * BASE) + ord(ch)) & MASK
        power[i + 1] = (power[i] * BASE) & MASK

    def get_hash(l, r):
        return (pref[r] - (pref[l] * power[r - l] & MASK)) & MASK

    # dp[i] = number of ways to split t[:i]
    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(m):
        if dp[i] == 0:
            continue
        for L in lengths:
            j = i + L
            if j > m:
                break
            h = get_hash(i, j)
            if h in by_len[L]:
                dp[j] += dp[i]
                if dp[j] >= MOD:
                    dp[j] -= MOD

    print(dp[m] % MOD)

if __name__ == "__main__":
    main()
